func TestStudioStructuralAssembly(t *testing.T) {
	server, err := New("v0.12.0")
	if err != nil {
		t.Fatal(err)
	}
	call := func(method string, params any) map[string]any {
		t.Helper()
		p, _ := json.Marshal(params)
		body, err := server.Call(context.Background(), method, p)
		if err != nil {
			t.Fatal(err)
		}
		var result map[string]any
		if err := json.Unmarshal(body, &result); err != nil {
			t.Fatal(err)
		}
		return result
	}
	documents := []any{}
	for _, name := range []string{"model.sysml", "views.sysml"} {
		content, err := os.ReadFile("testdata/studio-assembly/" + name)
		if err != nil {
			t.Fatal(err)
		}
		documents = append(documents, map[string]any{"name": name, "content": string(content)})
	}
	parsed := call("ParseSources", map[string]any{"strictConformance": true, "documents": documents})
	result := call("EvaluateView", map[string]any{"modelHash": parsed["modelHash"], "view": "AssemblyViews::structure"})
	if result["status"] != "complete" || result["renderStatus"] != "available" {
		t.Fatalf("%v", result)
	}
	artifact := result["artifact"].(map[string]any)
	nodes := map[string]map[string]any{}
	for _, raw := range artifact["nodes"].([]any) {
		node := raw.(map[string]any)
		nodes[node["name"].(string)] = node
	}
	if nodes["bay"]["parent"] != nodes["Assembly::Station"]["id"] || nodes["primary"]["parent"] != nodes["bay"]["id"] || nodes["standby"]["parent"] != nodes["bay"]["id"] {
		t.Fatalf("Incorrect nested ownership: %v", artifact)
	}
	if nodes["monitor"]["reference"] != true {
		t.Fatal("Reference modifier was lost")
	}
	ports := map[string]map[string]map[string]any{}
	for _, name := range []string{"primary", "standby", "monitor"} {
		ports[name] = map[string]map[string]any{}
		for _, raw := range nodes[name]["ports"].([]any) {
			port := raw.(map[string]any)
			ports[name][port["name"].(string)] = port
		}
		for port, direction := range map[string]string{"input": "in", "output": "out", "service": "inout"} {
			if ports[name][port]["direction"] != direction {
				t.Fatalf("Lost %s.%s direction: %v", name, port, ports[name][port])
			}
		}
	}
	edges := artifact["edges"].([]any)
	if len(edges) != 1 {
		t.Fatalf("Expected one resolved connector: %v", edges)
	}
	edge := edges[0].(map[string]any)
	if edge["from"] != nodes["primary"]["id"] || edge["fromPort"] != ports["primary"]["output"]["id"] || edge["to"] != nodes["standby"]["id"] || edge["toPort"] != ports["standby"]["input"]["id"] {
		t.Fatalf("Wrong port endpoints: %v", edge)
	}
	contexts := map[string]string{}
	for _, raw := range result["correspondence"].([]any) {
		item := raw.(map[string]any)
		if item["subject"].(map[string]any)["qualifiedName"] == "Assembly::Device::output" {
			data, _ := json.Marshal(item["context"])
			contexts[item["symbol"].(string)] = string(data)
		}
	}
	left := contexts[ports["primary"]["output"]["id"].(string)]
	right := contexts[ports["standby"]["output"]["id"].(string)]
	if left == "" || right == "" || left == right {
		t.Fatalf("Repeated ports lost their usage contexts: %v", contexts)
	}
	other := call("EvaluateView", map[string]any{"modelHash": parsed["modelHash"], "view": "AssemblyViews::devices"})
	if other["status"] != "complete" || other["renderStatus"] != "available" {
		t.Fatalf("%v", other)
	}
	notices := other["artifact"].(map[string]any)["notices"].([]any)
	found := false
	for _, raw := range notices {
		if strings.Contains(raw.(string), "Inspect") && strings.Contains(raw.(string), "not shown") {
			found = true
		}
	}
	if !found {
		t.Fatalf("Unsupported exposed behavior was not reported: %v", notices)
	}
}

func TestStudioEvaluatedView(t *testing.T) {
	server, err := New("v0.12.0")
	if err != nil {
		t.Fatal(err)
	}
	call := func(method string, params any) map[string]any {
		t.Helper()
		p, _ := json.Marshal(params)
		body, err := server.Call(context.Background(), method, p)
		if err != nil {
			t.Fatal(err)
		}
		var value map[string]any
		if err = json.Unmarshal(body, &value); err != nil {
			t.Fatal(err)
		}
		return value
	}
	model := `metadata def Safety;
 package Lib { #Safety part def A; part def B; port def Signal;
 part def Motor {inout port bus : Signal;}
 part def Rig {part left : Motor; part right : Motor; connection link connect left.bus to right.bus;}}
 `
	for _, test := range []struct {
		name, view, status, render string
		selected                   int
	}{
		{"wildcard", "view candidate : StandardViewDefinitions::GeneralView {expose Lib::*;}", "complete", "available", 5},
		{"filter", "view candidate : StandardViewDefinitions::GeneralView {filter @Safety; expose Lib::*;}", "complete", "available", 1},
		{"empty", "view candidate : StandardViewDefinitions::GeneralView {filter false; expose Lib::*;}", "complete", "available", 0},
		{"invalid-filter", "view candidate : StandardViewDefinitions::GeneralView {filter 7; expose Lib::*;}", "invalid", "unavailable", 0},
		{"missing-exposure", "view candidate : StandardViewDefinitions::GeneralView {expose Missing::Thing;}", "invalid", "unavailable", 0},
		{"geometry", "view candidate : StandardViewDefinitions::GeometryView {expose Lib::Rig;}", "complete", "unsupported", 1},
		{"pair", "view candidate : StandardViewDefinitions::InterconnectionView {expose Lib::Rig;}", "complete", "available", 1},
	} {
		t.Run(test.name, func(t *testing.T) {
			parsed := call("ParseSources", map[string]any{"strictConformance": true, "documents": []any{map[string]any{"name": "model.sysml", "content": model}, map[string]any{"name": "view.sysml", "content": test.view}}})
			result := call("EvaluateView", map[string]any{"modelHash": parsed["modelHash"], "view": "candidate"})
			if result["status"] != test.status || result["renderStatus"] != test.render {
				t.Fatalf("%v", result)
			}
			selected := result["selected"].([]any)
			if len(selected) != test.selected {
				t.Fatalf("selected %d: %v", len(selected), result)
			}
			if test.name == "pair" {
				correspondence := result["correspondence"].([]any)
				contexts := map[string]bool{}
				for _, raw := range correspondence {
					item := raw.(map[string]any)
					subject := item["subject"].(map[string]any)
					if subject["qualifiedName"] == "Lib::Motor::bus" {
						context, _ := json.Marshal(item["context"])
						contexts[string(context)] = true
						if subject["origin"] == nil {
							t.Fatal("Missing inherited port origin")
						}
					}
				}
				if len(contexts) != 2 {
					t.Fatalf("Expected distinct port contexts: %v", correspondence)
				}
			}
		})
	}
}

func TestStudioGeometryDimensions(t *testing.T) {
	server, err := New("v0.12.0")
	if err != nil {
		t.Fatal(err)
	}
	call := func(method string, params any) map[string]any {
		t.Helper()
		data, _ := json.Marshal(params)
		body, err := server.Call(context.Background(), method, data)
		if err != nil {
			t.Fatal(err)
		}
		var result map[string]any
		if err = json.Unmarshal(body, &result); err != nil {
			t.Fatal(err)
		}
		return result
	}
	for _, test := range []struct {
		name, body string
		available  bool
	}{
		{"box", `item crate : ShapeItems::Box { :>> length = 200 [SI::cm]; :>> width = 1 [SI::m]; :>> height = 0.5 [SI::m]; }`, true},
		{"missing", `item crate : ShapeItems::Box;`, false},
		{"not-box", `part def Crate; part crate : Crate;`, false},
		{"void", `item crate : ShapeItems::Box { :>> length = 2 [SI::m]; :>> width = 1 [SI::m]; :>> height = 1 [SI::m]; item :>> voids : ShapeItems::Cylinder { :>> radius = 0.1 [SI::m]; :>> height = 1 [SI::m]; } }`, false},
	} {
		t.Run(test.name, func(t *testing.T) {
			source := `package GeometryDemo { ` + test.body + ` view scene : StandardViewDefinitions::GeometryView { expose crate; } }`
			parsed := call("ParseSources", map[string]any{"strictConformance": true, "documents": []any{map[string]any{"name": "geometry.sysml", "content": source}}})
			result := call("EvaluateView", map[string]any{"modelHash": parsed["modelHash"], "view": "GeometryDemo::scene"})
			if test.available {
				if result["status"] != "complete" || result["renderStatus"] != "available" {
					t.Fatalf("%v", result)
				}
				artifact := result["artifact"].(map[string]any)
				nodes := artifact["nodes"].([]any)
				solid := nodes[0].(map[string]any)["solid"].(map[string]any)
				if solid["length"] != float64(2) || solid["width"] != float64(1) || solid["height"] != 0.5 {
					t.Fatalf("Expected normalized metre dimensions: %v", solid)
				}
				if len(result["correspondence"].([]any)) != 1 {
					t.Fatal("Missing solid source correspondence")
				}
			} else if result["renderStatus"] == "available" {
				t.Fatalf("Unsupported geometry was rendered: %v", result)
			}
		})
	}
}

func TestStudioGeometryPlacement(t *testing.T) {
	server, err := New("v0.12.0")
	if err != nil {
		t.Fatal(err)
	}
	call := func(method string, params any) map[string]any {
		t.Helper()
		data, _ := json.Marshal(params)
		body, err := server.Call(context.Background(), method, data)
		if err != nil {
			t.Fatal(err)
		}
		var result map[string]any
		if err = json.Unmarshal(body, &result); err != nil {
			t.Fatal(err)
		}
		return result
	}
	model := `package GeometryDemo {
 attribute datum : ISQ::CartesianSpatial3dCoordinateFrame { :>> mRefs = (SI::mm, SI::mm, SI::mm); }
 item crate : ShapeItems::Box {
 :>> length = 200 [SI::cm]; :>> width = 1 [SI::m]; :>> height = 0.5 [SI::m];
 attribute coordinateFrame : ISQ::CartesianSpatial3dCoordinateFrame {
 :>> mRefs = (SI::m, SI::m, SI::m);
 :>> transformation : MeasurementReferences::CoordinateFramePlacement {
 :>> source = datum; :>> origin = (3000.0, 2000.0, 1000.0) [datum];
 :>> basisDirections = ((0.0,1.0,0.0) [datum],(-1.0,0.0,0.0) [datum],(0.0,0.0,1.0) [datum]);
 }
 }
 }
 view scene : StandardViewDefinitions::GeometryView { expose crate; }
 }`
	parsed := call("ParseSources", map[string]any{"strictConformance": true, "documents": []any{map[string]any{"name": "geometry.sysml", "content": model}}})
	result := call("EvaluateView", map[string]any{"modelHash": parsed["modelHash"], "view": "GeometryDemo::scene"})
	if result["status"] != "complete" || result["renderStatus"] != "available" {
		t.Fatalf("%v", result)
	}
	node := result["artifact"].(map[string]any)["nodes"].([]any)[0].(map[string]any)
	placement, ok := node["placement"].(map[string]any)
	if !ok {
		t.Fatalf("No modeled placement: %v", node)
	}
	if placement["frame"] != "GeometryDemo::datum" {
		t.Fatalf("%v", placement)
	}
	origin := placement["origin"].([]any)
	if origin[0] != float64(3) || origin[1] != float64(2) || origin[2] != float64(1) {
		t.Fatalf("Unnormalized origin: %v", origin)
	}
	basis := placement["basis"].([]any)
	if basis[0].([]any)[1] != float64(-1) || basis[1].([]any)[0] != float64(1) {
		t.Fatalf("Incorrect evaluated orientation: %v", basis)
	}

	for _, invalid := range []string{
		strings.Replace(model, "(0.0,1.0,0.0) [datum]", "(0.0,0.0,0.0) [datum]", 1),
		strings.Replace(model, ":>> mRefs = (SI::m, SI::m, SI::m);", ":>> mRefs = (SI::s, SI::s, SI::s);", 1),
	} {
		parsed := call("ParseSources", map[string]any{"strictConformance": true, "documents": []any{map[string]any{"name": "geometry.sysml", "content": invalid}}})
		rejected := call("EvaluateView", map[string]any{"modelHash": parsed["modelHash"], "view": "GeometryDemo::scene"})
		if rejected["renderStatus"] == "available" {
			t.Fatalf("Invalid placement was rendered: %v", rejected)
		}
	}
}

func TestStudioDeclaredAttributeValues(t *testing.T) {
	server, err := New("v0.12.0")
	if err != nil {
		t.Fatal(err)
	}
	call := func(method string, params any) map[string]any {
		t.Helper()
		p, _ := json.Marshal(params)
		raw, err := server.Call(context.Background(), method, p)
		if err != nil {
			t.Fatal(err)
		}
		var out map[string]any
		if err := json.Unmarshal(raw, &out); err != nil {
			t.Fatal(err)
		}
		return out
	}
	source := "package P { private import ScalarValues::*; part def Battery { attribute capacityWh : Real default = 480.0; } part def Rover { part left : Battery; part right : Battery; } } package V { private import StandardViewDefinitions::*; view architecture : InterconnectionView { expose P::Rover; } }"
	parsed := call("ParseSources", map[string]any{"strictConformance": true, "documents": []any{map[string]any{"name": "model.sysml", "content": source}}})
	result := call("EvaluateView", map[string]any{"modelHash": parsed["modelHash"], "view": "V::architecture"})
	if result["status"] != "complete" {
		t.Fatalf("%v", result)
	}
	found := 0
	for _, raw := range result["artifact"].(map[string]any)["nodes"].([]any) {
		n := raw.(map[string]any)
		if n["name"] == "left" || n["name"] == "right" {
			values := n["attributeDeclarations"].([]any)
			if len(values) != 1 || values[0] != "attribute capacityWh : Real default = 480.0;" {
				t.Fatalf("%v", n)
			}
			found++
		}
	}
	if found != 2 {
		t.Fatalf("Expected two independently typed usages, found %d", found)
	}
}

func TestStudioRetainsDeclaredBoundaryConnections(t *testing.T) {
	server, err := New("v0.12.0")
	if err != nil {
		t.Fatal(err)
	}
	call := func(method string, params any) map[string]any {
		t.Helper()
		body, _ := json.Marshal(params)
		raw, err := server.Call(context.Background(), method, body)
		if err != nil {
			t.Fatal(err)
		}
		var out map[string]any
		if err := json.Unmarshal(raw, &out); err != nil {
			t.Fatal(err)
		}
		return out
	}
	parsed := call("ParseSources", map[string]any{"strictConformance": true, "documents": []any{map[string]any{"name": "model.sysml", "content": `package P {
 port def Signal;
 part def Sender { out port p : Signal; }
 part def Receiver { in port p : Signal; }
 part def Subsystem {
  part sender : Sender; part receiver : Receiver;
  connection internal connect sender.p to receiver.p;
 }
 part def System {
  part a : Subsystem; part b : Subsystem;
  connection bridge connect a.sender.p to b.receiver.p;
 }
 view v : StandardViewDefinitions::InterconnectionView { expose System; }
}`}}})
	result := call("EvaluateView", map[string]any{"modelHash": parsed["modelHash"], "view": "P::v"})
	if result["status"] != "complete" || result["renderStatus"] != "available" {
		t.Fatalf("%v", result)
	}
	artifact := result["artifact"].(map[string]any)
	nodes := artifact["nodes"].([]any)
	edges := artifact["edges"].([]any)
	if len(nodes) != 7 || len(edges) != 1 {
		t.Fatalf("Effective internals or declared bridge lost: %v", artifact)
	}
	edge := edges[0].(map[string]any)
	if edge["from"] != "n3" || edge["to"] != "n6" || edge["fromPort"] != "n3.0" || edge["toPort"] != "n6.0" || edge["label"] != "bridge" {
		t.Fatalf("Incorrect retained usage boundaries: %v", edge)
	}
}

func TestStudioExposureMembershipScope(t *testing.T) {
	server, err := New("v0.12.0")
	if err != nil {
		t.Fatal(err)
	}
	call := func(method string, params any) map[string]any {
		t.Helper()
		input, err := json.Marshal(params)
		if err != nil {
			t.Fatal(err)
		}
		raw, err := server.Call(context.Background(), method, input)
		if err != nil {
			t.Fatal(err)
		}
		var result map[string]any
		if err := json.Unmarshal(raw, &result); err != nil {
			t.Fatal(err)
		}
		return result
	}
	errorsOf := func(parsed map[string]any) []string {
		var errors []string
		diagnostics, _ := parsed["diagnostics"].([]any)
		for _, item := range diagnostics {
			d := item.(map[string]any)
			if d["severity"] == "error" {
				errors = append(errors, d["message"].(string))
			}
		}
		return errors
	}
	const demo = "package Demo { part def Sat; }\n"
	evaluate := func(source, view string) map[string]string {
		t.Helper()
		parsed := call("ParseSources", map[string]any{"strictConformance": true, "documents": []any{map[string]any{"name": "model.sysml", "content": demo + source}}})
		if errors := errorsOf(parsed); len(errors) > 0 {
			t.Fatalf("positive fixture rejected: %v", errors)
		}
		result := call("EvaluateView", map[string]any{"modelHash": parsed["modelHash"], "view": view})
		if result["status"] != "complete" || result["renderStatus"] != "available" {
			t.Fatalf("unavailable view: %v", result)
		}
		selected, ok := result["selected"].([]any)
		if !ok {
			t.Fatalf("missing selected membership: %v", result)
		}
		names := map[string]string{}
		for _, raw := range selected {
			subject := raw.(map[string]any)
			origin, ok := subject["origin"].(map[string]any)
			if !ok || origin["file"] == "" || subject["id"] == "" {
				t.Fatalf("selected subject lacks source identity: %v", subject)
			}
			name, ok := subject["qualifiedName"].(string)
			if !ok || name == "" {
				t.Fatalf("selected subject lacks qualified name: %v", subject)
			}
			names[name] = origin["file"].(string)
		}
		return names
	}
	body := func(visibility, exposure string) string {
		return "package Probe { " + visibility + " import Demo::*; " + visibility + " import StandardViewDefinitions::*; part p : Sat; view star : GeneralView { expose " + exposure + "; } }"
	}
	private := evaluate(body("private", "Probe::*"), "Probe::star")
	public := evaluate(body("public", "Probe::*"), "Probe::star")
	if !reflect.DeepEqual(private, public) {
		t.Fatalf("exposure must ignore import visibility: private=%v public=%v", private, public)
	}
	for _, name := range []string{"Probe::p", "Probe::star", "Demo::Sat", "StandardViewDefinitions::GeneralView", "SysML::Systems::PartDefinition"} {
		if _, ok := private[name]; !ok {
			t.Fatalf("missing admitted membership %s", name)
		}
	}
	hasLibrary := false
	for _, file := range private {
		if file != "model.sysml" {
			hasLibrary = true
		}
	}
	if !hasLibrary {
		t.Fatal("wildcard exposure unexpectedly removed imported library memberships")
	}
	explicit := evaluate(body("private", "Probe::p"), "Probe::star")
	if !reflect.DeepEqual(explicit, map[string]string{"Probe::p": "model.sysml"}) {
		t.Fatalf("explicit exposure widened: %v", explicit)
	}
	named := evaluate("package Probe { private import Demo::Sat; private import StandardViewDefinitions::GeneralView; part p : Sat; view star : GeneralView { expose Probe::*; } }", "Probe::star")
	expected := map[string]bool{"Probe::p": true, "Probe::star": true, "Demo::Sat": true, "StandardViewDefinitions::GeneralView": true}
	if len(named) != len(expected) {
		t.Fatalf("named imports selected unexpected memberships: %v", named)
	}
	for name := range named {
		if !expected[name] {
			t.Fatalf("named import leaked %s", name)
		}
	}
	noImports := evaluate("package Probe { part p : Demo::Sat; view star : StandardViewDefinitions::GeneralView { expose Probe::*; } }", "Probe::star")
	if !reflect.DeepEqual(noImports, map[string]string{"Probe::p": "model.sysml", "Probe::star": "model.sysml"}) {
		t.Fatalf("no-import scope widened: %v", noImports)
	}
	hidden := evaluate("package Probe { private part hidden : Demo::Sat; } view star : StandardViewDefinitions::GeneralView { expose Probe::hidden; }", "star")
	if !reflect.DeepEqual(hidden, map[string]string{"Probe::hidden": "model.sysml"}) {
		t.Fatalf("explicit private exposure failed: %v", hidden)
	}
	for _, outside := range []string{"part q : Probe::Sat;", "private import Probe::*; part q : Sat;"} {
		source := demo + "package Probe { private import Demo::*; } package Outside { " + outside + " }"
		parsed := call("ParseSources", map[string]any{"strictConformance": true, "documents": []any{map[string]any{"name": "model.sysml", "content": source}}})
		errors := errorsOf(parsed)
		if len(errors) == 0 {
			t.Fatalf("ordinary lookup bypassed private import visibility: %s", outside)
		}
		targetNamed := false
		for _, message := range errors {
			if strings.Contains(message, "Sat") {
				targetNamed = true
			}
		}
		if !targetNamed {
			t.Fatalf("ordinary lookup failed for unrelated reason: %v", errors)
		}
	}
}

// TestStudioAuthoredEffectiveOccurrences fixes the pinned bridge contract at the
// declaration and occurrence level. Expected values are retained native evidence,
// not computed from the implementation under test. Explore expectations are the
// complete pre-expansion envelopes; source and view identity remain independent.
func TestStudioAuthoredEffectiveOccurrences(t *testing.T) {
	for _, tc := range issue18Cases {
		t.Run(tc.name, func(t *testing.T) {
			server, err := New("v0.12.0")
			if err != nil {
				t.Fatal(err)
			}
			call := func(method string, params any) map[string]any {
				t.Helper()
				body, err := json.Marshal(params)
				if err != nil {
					t.Fatal(err)
				}
				raw, err := server.Call(context.Background(), method, body)
				if err != nil {
					t.Fatal(err)
				}
				var out map[string]any
				if err := json.Unmarshal(raw, &out); err != nil {
					t.Fatal(err)
				}
				return out
			}
			parsed := call("ParseSources", map[string]any{"strictConformance": true, "documents": []any{map[string]any{"name": "probe.sysml", "content": tc.source}}})
			view, subject := "V::v", "P::sat1"
			if tc.name == "declared-boundary" {
				view, subject = "P::v", "P::System"
			}
			result := call("EvaluateView", map[string]any{"modelHash": parsed["modelHash"], "view": view})
			if result["status"] != "complete" || result["renderStatus"] != "available" {
				t.Fatalf("invalid view: %v", result)
			}
			assertIssue18JSON(t, "authored declarations, topology and occurrence bindings", issue18Semantics(t, result, tc.source), tc.want)
			assertIssue18JSON(t, "unchanged selected scope", result["selected"], tc.selected)
			explored := call("Explore", map[string]any{"modelHash": parsed["modelHash"], "request": map[string]any{"scope": map[string]any{"kind": "element", "subject": subject}, "representation": "interconnection"}})
			assertIssue18JSON(t, "unchanged complete Explore envelope", explored, tc.explore)
			// Every legacy-visible node, port and correspondence keeps its complete
			// value, including ordinals on a later sibling following new descendants.
			got := issue18Semantics(t, result, tc.source).([]any)
			var legacy []any
			if err := json.Unmarshal([]byte(tc.legacy), &legacy); err != nil {
				t.Fatal(err)
			}
			byID := map[string]any{}
			for _, raw := range got {
				r := raw.(map[string]any)
				byID[r["symbol"].(string)] = raw
			}
			for _, raw := range legacy {
				r := raw.(map[string]any)
				id := r["symbol"].(string)
				if !reflect.DeepEqual(byID[id], raw) {
					t.Errorf("legacy identity %s changed: got %v want %v", id, byID[id], raw)
				}
			}
		})
	}
}

func assertIssue18JSON(t *testing.T, label string, got any, expected string) {
	t.Helper()
	var want any
	if err := json.Unmarshal([]byte(expected), &want); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(got, want) {
		b, _ := json.Marshal(got)
		t.Fatalf("%s\ngot: %s\nwant: %s", label, b, expected)
	}
}

func issue18Semantics(t *testing.T, result map[string]any, source string) any {
	t.Helper()
	artifact := result["artifact"].(map[string]any)
	bindings := map[string]map[string]any{}
	for _, raw := range result["correspondence"].([]any) {
		c := raw.(map[string]any)
		id := c["symbol"].(string)
		if bindings[id] != nil {
			t.Fatalf("duplicate binding %s", id)
		}
		bindings[id] = c
	}
	var rows []any
	contexts := map[string][]any{}
	ports := map[string]string{}
	seen := map[string]bool{}
	add := func(symbol string, value map[string]any, parent string) {
		t.Helper()
		c := bindings[symbol]
		if c == nil {
			t.Fatalf("missing binding %s", symbol)
		}
		subject := c["subject"].(map[string]any)
		origin := subject["origin"].(map[string]any)
		start, length := int(origin["offset"].(float64)), int(origin["length"].(float64))
		if origin["file"] != "probe.sysml" || start < 0 || length < 1 || start+length > len(source) {
			t.Fatalf("invalid origin %v", origin)
		}
		ctx := c["context"].([]any)
		want := append(append([]any{}, contexts[parent]...), subject["id"])
		if !reflect.DeepEqual(ctx, want) {
			t.Fatalf("%s incomplete occurrence context: %v want %v", symbol, ctx, want)
		}
		contexts[symbol] = ctx
		rows = append(rows, map[string]any{"symbol": symbol, "value": value, "binding": c, "declaration": source[start : start+length]})
	}
	for _, raw := range artifact["nodes"].([]any) {
		n := raw.(map[string]any)
		id := n["id"].(string)
		parent, _ := n["parent"].(string)
		if seen[id] || (parent != "" && !seen[parent]) {
			t.Fatalf("duplicate or non-parent-first node %v", n)
		}
		seen[id] = true
		add(id, n, parent)
		if ps, ok := n["ports"].([]any); ok {
			for _, raw := range ps {
				port := raw.(map[string]any)
				pid := port["id"].(string)
				if ports[pid] != "" {
					t.Fatalf("duplicate port %s", pid)
				}
				ports[pid] = id
				add(pid, port, id)
			}
		}
	}
	for i, raw := range artifact["edges"].([]any) {
		e := raw.(map[string]any)
		for _, end := range []string{"from", "to"} {
			node := e[end].(string)
			if !seen[node] {
				t.Fatalf("missing endpoint %v", e)
			}
			if pin, ok := e[end+"Port"].(string); ok && ports[pin] != node {
				t.Fatalf("wrong endpoint port %v", e)
			}
		}
		// Connector contexts are intentionally not expanded in this bounded policy.
		id := "edge:" + strconv.Itoa(i)
		c := bindings[id]
		if c == nil {
			t.Fatalf("missing edge binding %s", id)
		}
		subject := c["subject"].(map[string]any)
		o := subject["origin"].(map[string]any)
		start, length := int(o["offset"].(float64)), int(o["length"].(float64))
		rows = append(rows, map[string]any{"symbol": id, "value": e, "binding": c, "declaration": source[start : start+length]})
	}
	return rows
}

